import React, { ReactNode, useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import AnimatedText from './AnimatedText';

interface AnimatedContentProps {
  children: ReactNode;
  routeKey: string; // Used to trigger animations on route changes
}

/**
 * This component wraps page content and handles:
 * 1. Page transitions (fade in/out)
 * 2. Text animations with Claude-like typing effect
 * 
 * It processes React children to find text nodes and wrap them in AnimatedText
 */
const AnimatedContent: React.FC<AnimatedContentProps> = ({ children, routeKey }) => {
  const [isAnimating, setIsAnimating] = useState(false);
  const [showContent, setShowContent] = useState(true);

  // Handle page transitions
  useEffect(() => {
    setIsAnimating(true);
    setShowContent(false);

    // Short delay before showing new content
    const timer = setTimeout(() => {
      setShowContent(true);
    }, 100);

    return () => clearTimeout(timer);
  }, [routeKey]);

  // Page transition variants
  const pageVariants = {
    initial: { opacity: 0.9 },
    animate: { opacity: 1, transition: { duration: 0.1 } },
    exit: { opacity: 0.9, transition: { duration: 0.1 } }
  };

  // Process React children to wrap text content in AnimatedText components
  const processChildren = (children: ReactNode): ReactNode => {
    return React.Children.map(children, child => {
      // Handle text nodes directly
      if (typeof child === 'string') {
        return <AnimatedText text={child} />;
      }

      // Skip non-react elements
      if (!React.isValidElement(child)) {
        return child;
      }

      // Skip certain elements we don't want to animate
      const excludedElements = ['img', 'button', 'input', 'textarea'];
      if (excludedElements.includes(child.type as string)) {
        return child;
      }

      // Special handling for common text elements
      const textElements = ['p', 'h1', 'h2', 'h3', 'h4', 'span', 'li', 'a'];
      if (textElements.includes(child.type as string) && 
          React.Children.count(child.props.children) === 1 &&
          typeof child.props.children === 'string') {
        // Simple text element with just a string as child
        const text = child.props.children;
        const elementType = child.type as 'p' | 'h1' | 'h2' | 'h3' | 'h4' | 'span' | 'div';

        // Return AnimatedText with the same element type and props
        return React.cloneElement(
          <AnimatedText 
            text={text} 
            element={elementType}
            className={child.props.className || ''}
          />,
          { ...child.props, children: undefined }
        );
      }

      // For elements with multiple children, recursively process them
      if (child.props.children) {
        const newChildren = processChildren(child.props.children);
        return React.cloneElement(child, { ...child.props, children: newChildren });
      }

      // Default: return unchanged
      return child;
    });
  };

  // Mark animation as complete for performance
  const handleAnimationComplete = () => {
    setIsAnimating(false);
  };

  return (
    <AnimatePresence mode="wait">
      <motion.div
        key={routeKey}
        initial="initial"
        animate="animate"
        exit="exit"
        variants={pageVariants}
        className="animated-content-wrapper"
        onAnimationComplete={handleAnimationComplete}
      >
        {showContent ? processChildren(children) : null}
      </motion.div>
    </AnimatePresence>
  );
};

export default AnimatedContent;
